// ──────────────────────────── tests ──────────────────────────────────────

test('keeps width and height as plain properties', () => {
  const r = makeRectangle(3, 4);
  eq(r.width, 3);
  eq(r.height, 4);
});

test('area multiplies the two sides', () => {
  eq(makeRectangle(3, 4).area(), 12);
  eq(makeRectangle(5, 5).area(), 25);
});

test('scaleBy grows both sides', () => {
  const r = makeRectangle(3, 4);
  r.scaleBy(2);
  eq(r.width, 6);
  eq(r.height, 8);
});

test('scaleBy returns the object so calls chain', () => {
  const r = makeRectangle(2, 2);
  eq(r.scaleBy(2).scaleBy(3).area(), 144);
});

test('describe reads the size at the moment it is called', () => {
  const r = makeRectangle(3, 4);
  eq(r.describe(), '3x4 rectangle');
  eq(r.scaleBy(10).describe(), '30x40 rectangle');
});

test('each rectangle carries its own state', () => {
  const a = makeRectangle(1, 1);
  const b = makeRectangle(2, 2);
  a.scaleBy(5);
  eq(a.area(), 25);
  eq(b.area(), 4);
});

test('each rectangle also carries its own copy of every method', () => {
  const a = makeRectangle(1, 1);
  const b = makeRectangle(1, 1);
  ok(a.area !== b.area, 'literals duplicate their methods per object');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('tally counts repeated words', () => {
  eq(tally(['a', 'b', 'a', 'a']), { a: 3, b: 1 });
});

test('tally returns an empty object for an empty list', () => {
  eq(tally([]), {});
});

test('tally is not fooled by inherited property names', () => {
  eq(tally(['toString', 'valueOf', 'toString']), {
    toString: 2,
    valueOf: 1,
  });
});

test('renameKey renames one key and keeps the rest', () => {
  eq(renameKey({ id: 1, nm: 'Ada' }, 'nm', 'name'), { id: 1, name: 'Ada' });
});

test('renameKey leaves the original object untouched', () => {
  const original = { nm: 'Ada' };
  const renamed = renameKey(original, 'nm', 'name');
  eq(original, { nm: 'Ada' });
  eq(renamed, { name: 'Ada' });
});

test('renameKey copies unchanged when the key is missing', () => {
  const original = { id: 1 };
  const copy = renameKey(original, 'nope', 'name');
  eq(copy, { id: 1 });
  eq(copy === original, false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('reads back the celsius it was built with', () => {
  const t = makeThermometer(21);
  eq(t.celsius, 21);
});

test('fahrenheit is derived from celsius', () => {
  const t = makeThermometer(100);
  approx(t.fahrenheit, 212);
  t.celsius = 37;
  approx(t.fahrenheit, 98.6, 1e-9);
});

test('writing fahrenheit updates celsius', () => {
  const t = makeThermometer(0);
  t.fahrenheit = 212;
  approx(t.celsius, 100);
});

test('-40 is the same number in both scales', () => {
  const t = makeThermometer(-40);
  approx(t.fahrenheit, -40);
});

test('the celsius setter refuses temperatures below absolute zero', () => {
  const t = makeThermometer(0);
  throws(() => {
    t.celsius = -300;
  }, 'below absolute zero');
  eq(t.celsius, 0, 'a rejected write must not change the state');
});

test('the fahrenheit setter reuses the same guard', () => {
  const t = makeThermometer(0);
  throws(() => {
    t.fahrenheit = -500;
  }, 'below absolute zero');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('starts at zero by default', () => {
  eq(createCounter().count(), 0);
});

test('starts at the number it was given', () => {
  eq(createCounter(10).count(), 10);
});

test('inc adds one, or the step you pass', () => {
  const c = createCounter();
  eq(c.inc(), 1);
  eq(c.inc(5), 6);
  eq(c.count(), 6);
});

test('reset goes back to the starting value, not to zero', () => {
  const c = createCounter(10);
  c.inc(5);
  eq(c.reset(), 10);
  eq(c.count(), 10);
});

test('two counters never share state', () => {
  const a = createCounter();
  const b = createCounter();
  a.inc();
  a.inc();
  eq(a.count(), 2);
  eq(b.count(), 0);
});

test('the number itself is not reachable from outside', () => {
  const c = createCounter(7);
  ok(
    Object.values(c).every((v) => typeof v === 'function'),
    'only methods should be exposed'
  );
});

test('but every counter pays for its own copy of every method', () => {
  const a = createCounter();
  const b = createCounter();
  ok(a.inc !== b.inc, 'closures cannot be shared between objects');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('new Counter() starts at zero', () => {
  const c = new Counter();
  eq(c.count, 0);
});

test('new Counter(7) starts at seven', () => {
  const c = new Counter(7);
  eq(c.count, 7);
});

test('inc bumps the count and returns it', () => {
  const c = new Counter();
  eq(c.inc(), 1);
  eq(c.inc(5), 6);
  eq(c.count, 6);
});

test('reset goes back to the starting value', () => {
  const c = new Counter(10);
  c.inc(3);
  eq(c.reset(), 10);
});

test('the methods are not on the instance — they are inherited', () => {
  const c = new Counter();
  eq(Object.hasOwn(c, 'inc'), false);
  eq(Object.keys(c).sort(), ['count', 'start']);
});

test('every instance shares one single copy of each method', () => {
  const a = new Counter();
  const b = new Counter();
  ok(a.inc === b.inc);
  ok(a.inc === Counter.prototype.inc);
});

test('instances are linked to Counter.prototype', () => {
  const c = new Counter();
  ok(c instanceof Counter);
  ok(Object.getPrototypeOf(c) === Counter.prototype);
  ok(Counter.prototype.constructor === Counter);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('runs the constructor body against a fresh object', () => {
  const p = myNew(Point, 1, 2);
  eq(p.x, 1);
  eq(p.y, 2);
});

test('links the new object to Ctor.prototype', () => {
  const p = myNew(Point, 0, 0);
  ok(Object.getPrototypeOf(p) === Point.prototype);
  ok(p instanceof Point);
});

test('so inherited methods work on it', () => {
  const p = myNew(Point, 3, 4);
  eq(p.toString(), '(3, 4)');
  eq(Object.hasOwn(p, 'toString'), false);
});

test('forwards every argument in order', () => {
  const p = myNew(Point, 'a', 'b');
  eq([p.x, p.y], ['a', 'b']);
});

test('two calls produce two independent objects', () => {
  const a = myNew(Point, 1, 1);
  const b = myNew(Point, 2, 2);
  a.x = 99;
  eq(b.x, 2);
});

test('an object returned by the constructor wins', () => {
  const s = myNew(Sneaky);
  eq(s, { replaced: true });
  eq(s.hidden, undefined);
  eq(s instanceof Sneaky, false);
});

test('a primitive returned by the constructor is ignored', () => {
  const a = myNew(Adder, 5);
  eq(a.n, 5);
  ok(a instanceof Adder);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('greet reads the name of the object it was called on', () => {
  eq(createRobot('Ada').greet(), 'Hi, I am Ada');
  eq(createRobot('Bob').greet(), 'Hi, I am Bob');
});

test('the shared behaviour object IS the prototype', () => {
  const r = createRobot('Ada');
  ok(Object.getPrototypeOf(r) === robotBehaviour);
});

test('only `name` is an own property — greet is borrowed', () => {
  const r = createRobot('Ada');
  eq(Object.keys(r), ['name']);
  eq(Object.hasOwn(r, 'greet'), false);
  eq('greet' in r, true);
});

test('every robot uses the very same function object', () => {
  const a = createRobot('Ada');
  const b = createRobot('Bob');
  ok(a.greet === b.greet);
  ok(a.greet === robotBehaviour.greet);
});

test('rename changes the instance and returns it for chaining', () => {
  const a = createRobot('Ada');
  const b = createRobot('Bob');
  eq(a.rename('Zed').greet(), 'Hi, I am Zed');
  eq(b.greet(), 'Hi, I am Bob', 'the prototype must not be touched');
});

test('a method added to the prototype later shows up immediately', () => {
  const r = createRobot('Ada');
  robotBehaviour.shout = function () {
    return `${this.name.toUpperCase()}!`;
  };
  eq(r.shout(), 'ADA!', 'lookup happens at call time, not at creation');
});

test('assigning on the instance shadows the shared method', () => {
  const a = createRobot('Ada');
  const b = createRobot('Bob');
  a.greet = () => 'custom';
  eq(a.greet(), 'custom');
  eq(b.greet(), 'Hi, I am Bob');
  eq(Object.hasOwn(a, 'greet'), true);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('ownKeys lists only what the object itself holds', () => {
  eq(ownKeys(makeDog()), ['name']);
  eq(ownKeys({ b: 1, a: 2 }), ['a', 'b']);
});

test('ownKeys is empty for an object that owns nothing', () => {
  eq(ownKeys(Object.create(animalBase)), []);
});

test('inheritedKeys reports what the prototype supplies', () => {
  eq(inheritedKeys(makeDog()), ['kind', 'speak']);
});

test('inheritedKeys is empty for a plain literal', () => {
  eq(inheritedKeys({ a: 1 }), []);
});

test('a shadowed key counts as own, never as inherited', () => {
  const dog = makeDog();
  dog.kind = 'pet';
  eq(ownKeys(dog), ['kind', 'name']);
  eq(inheritedKeys(dog), ['speak']);
});

test('allPropertyNames reaches the built-ins on Object.prototype', () => {
  const names = allPropertyNames({ a: 1 });
  ok(names.includes('a'));
  ok(names.includes('hasOwnProperty'), 'non-enumerable, but still there');
  ok(names.includes('toString'));
});

test('allPropertyNames lists a shadowed name exactly once', () => {
  const dog = makeDog();
  dog.kind = 'pet';
  const names = allPropertyNames(dog);
  eq(names.filter((n) => n === 'kind').length, 1);
});

test('an object with no prototype has nothing but its own keys', () => {
  const bare = Object.create(null);
  bare.a = 1;
  eq(allPropertyNames(bare), ['a']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a new playlist knows its name and is empty', () => {
  const p = new Playlist('Road trip');
  eq(p.name, 'Road trip');
  eq(p.size, 0);
  ok(p instanceof Playlist);
});

test('add appends tracks in order and chains', () => {
  const p = new Playlist('Mix');
  p.add('Roam').add('Debaser');
  eq(p.toArray(), ['Roam', 'Debaser']);
  eq(p.size, 2);
});

test('adding a duplicate changes nothing', () => {
  const p = new Playlist('Mix');
  p.add('Roam').add('Roam');
  eq(p.toArray(), ['Roam']);
  eq(p.has('Roam'), true);
  eq(p.has('Nope'), false);
});

test('remove reports whether it actually removed something', () => {
  const p = new Playlist('Mix');
  p.add('Roam').add('Debaser');
  eq(p.remove('Roam'), true);
  eq(p.remove('Roam'), false);
  eq(p.toArray(), ['Debaser']);
});

test('toArray hands back a copy, not the live array', () => {
  const p = new Playlist('Mix');
  p.add('Roam');
  const snapshot = p.toArray();
  snapshot.push('Sneaky');
  eq(p.size, 1);
});

test('every playlist gets its own tracks array', () => {
  const a = new Playlist('A');
  const b = new Playlist('B');
  a.add('Roam');
  eq(b.size, 0);
});

test('the methods live on the prototype, the fields on the instance', () => {
  const p = new Playlist('Mix');
  eq(Object.hasOwn(p, 'add'), false);
  eq(Object.keys(p).sort(), ['name', 'tracks']);
  ok(Object.getPrototypeOf(p) === Playlist.prototype);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a class field lands on the instance', () => {
  eq(whereDoesItLive(new Tag('a'), 'clicks'), 'own');
});

test('so does anything the constructor assigns', () => {
  eq(whereDoesItLive(new Tag('a'), 'label'), 'own');
});

test('methods do NOT — they live on Tag.prototype', () => {
  eq(whereDoesItLive(new Tag('a'), 'render'), 'prototype');
  eq(whereDoesItLive(new Tag('a'), 'loud'), 'prototype');
});

test('the chain keeps going past Tag.prototype', () => {
  eq(whereDoesItLive(new Tag('a'), 'toString'), 'prototype');
});

test('unknown keys are missing, not own', () => {
  eq(whereDoesItLive(new Tag('a'), 'nope'), 'missing');
});

test('methodNames finds every method the class declared', () => {
  eq(methodNames(Tag), ['bump', 'loud', 'render']);
});

test('it works the same on a constructor function', () => {
  function Legacy() {}
  Legacy.prototype.ping = function () {};
  eq(methodNames(Legacy), ['ping']);
});

test('fields are enumerable, methods are not', () => {
  const t = new Tag('a');
  eq(whereDoesItLive(t, 'render'), 'prototype');
  eq(Object.keys(t).sort(), ['clicks', 'label']);
  eq(Object.keys(Tag.prototype), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the opening balance is readable through the getter', () => {
  const a = new BankAccount('Ada', 100);
  eq(a.owner, 'Ada');
  eq(a.balance, 100);
  eq(new BankAccount('Bob').balance, 0);
});

test('deposit and withdraw return the new balance', () => {
  const a = new BankAccount('Ada', 100);
  eq(a.deposit(50), 150);
  eq(a.withdraw(20), 130);
  eq(a.balance, 130);
});

test('withdrawing more than you have is refused', () => {
  const a = new BankAccount('Ada', 100);
  throws(() => a.withdraw(500), 'insufficient funds');
  eq(a.balance, 100, 'a refused withdrawal must not change anything');
});

test('the shared validator rejects junk amounts', () => {
  const a = new BankAccount('Ada', 100);
  throws(() => a.deposit(-1), 'positive number');
  throws(() => a.deposit(0), 'positive number');
  throws(() => a.withdraw('10'), 'positive number');
  eq(a.balance, 100);
});

test('the balance is invisible from outside the class', () => {
  const a = new BankAccount('Ada', 100);
  eq(Object.keys(a), ['owner']);
  eq(Object.getOwnPropertyNames(a), ['owner']);
  eq(JSON.stringify(a), '{"owner":"Ada"}');
});

test('and unwritable — the getter has no setter', () => {
  const a = new BankAccount('Ada', 100);
  throws(() => {
    a.balance = 999;
  });
  eq(a.balance, 100);
});

test('the brand check recognises real accounts only', () => {
  const a = new BankAccount('Ada', 100);
  eq(BankAccount.isAccount(a), true);
  eq(BankAccount.isAccount({ owner: 'Ada', balance: 100 }), false);
  eq(BankAccount.isAccount(null), false);
  eq(BankAccount.isAccount(42), false);
});

test('two accounts hold two separate balances', () => {
  const a = new BankAccount('Ada', 100);
  const b = new BankAccount('Bob', 100);
  a.deposit(1);
  eq(b.balance, 100);
  ok(a.deposit === b.deposit, 'the method itself is still shared');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('create hands out increasing ids', () => {
  User.reset();
  eq(User.create('Ada').id, 1);
  eq(User.create('Bob').id, 2);
  eq(User.create('Cy').id, 3);
});

test('find returns the very same instance', () => {
  User.reset();
  const ada = User.create('Ada');
  ok(User.find(1) === ada);
  eq(User.find(99), undefined);
});

test('count tracks the registry, reset empties it', () => {
  User.reset();
  User.create('Ada');
  User.create('Bob');
  eq(User.count, 2);
  User.reset();
  eq(User.count, 0);
  eq(User.create('Zed').id, 1, 'ids restart after a reset');
});

test('create trims the name and describe formats it', () => {
  User.reset();
  const ada = User.create('  Ada  ');
  eq(ada.name, 'Ada');
  eq(ada.describe(), '#1 Ada');
});

test('the validator is shared by create and rename', () => {
  User.reset();
  const ada = User.create('Ada');
  eq(User.isValidName('Ada'), true);
  eq(User.isValidName('   '), false);
  eq(User.isValidName(42), false);
  throws(() => User.create(''), 'name is required');
  throws(() => ada.rename('  '), 'name is required');
  eq(ada.name, 'Ada', 'a refused rename changes nothing');
});

test('rename works and chains', () => {
  User.reset();
  const ada = User.create('Ada');
  eq(ada.rename('Ada L.').describe(), '#1 Ada L.');
});

test('statics belong to the class, not to instances', () => {
  User.reset();
  const ada = User.create('Ada');
  eq(ada.create, undefined);
  eq(ada.count, undefined);
  ok(typeof User.create === 'function');
  eq(Object.hasOwn(User.prototype, 'create'), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('each subclass computes its own area', () => {
  approx(new Circle(2).area(), Math.PI * 4);
  eq(new Rectangle(3, 4).area(), 12);
  eq(new Square(5).area(), 25);
});

test('describe is written once on the base and used by all', () => {
  eq(new Circle(1).describe(), 'circle with area 3.14');
  eq(new Rectangle(3, 4).describe(), 'rectangle with area 12.00');
  eq(new Square(4).describe(), 'square with area 16.00');
});

test('the inherited describe calls the subclass area', () => {
  const c = new Circle(1);
  eq(Object.hasOwn(Object.getPrototypeOf(c), 'describe'), false);
  ok(Object.hasOwn(Circle.prototype, 'area'));
});

test('the abstract base refuses to compute an area', () => {
  const blob = new Shape('blob');
  throws(() => blob.area(), 'subclasses must implement area()');
  throws(() => blob.describe(), 'subclasses must implement area()');
});

test('the prototype chain is three links deep for a Square', () => {
  const s = new Square(2);
  ok(s instanceof Square);
  ok(s instanceof Rectangle);
  ok(s instanceof Shape);
  ok(Object.getPrototypeOf(Square.prototype) === Rectangle.prototype);
  ok(Object.getPrototypeOf(Rectangle.prototype) === Shape.prototype);
});

test('Square reuses Rectangle by passing the side twice', () => {
  const s = new Square(3);
  eq(s.width, 3);
  eq(s.height, 3);
  eq(s.name, 'square');
});

test('a mixed list describes itself with no if-statements', () => {
  const shapes = [new Circle(1), new Rectangle(2, 3), new Square(4)];
  eq(shapes.map((s) => s.describe()), [
    'circle with area 3.14',
    'rectangle with area 6.00',
    'square with area 16.00',
  ]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the base order totals its lines', () => {
  const o = new Order(items);
  eq(o.subtotal, 30);
  eq(o.total(), 30);
});

test('the discount layer overrides total', () => {
  const o = new DiscountedOrder(items, 10);
  approx(o.total(), 27);
  eq(o.subtotal, 30, 'the inherited getter is untouched');
});

test('express stacks shipping on top of the discounted total', () => {
  const o = new ExpressOrder(items, 10, 4.99);
  approx(o.total(), 31.99, 1e-9);
});

test('summary chains through super too', () => {
  eq(new Order(items).summary(), '2 items, $30.00');
  eq(new DiscountedOrder(items, 10).summary(), '2 items, $27.00 (10% off)');
});

test('express inherits the discounted summary but not its total', () => {
  const o = new ExpressOrder(items, 10, 4.99);
  eq(o.summary(), '2 items, $31.99 (10% off)');
  eq(Object.hasOwn(ExpressOrder.prototype, 'summary'), false);
});

test('an express order is all three types at once', () => {
  const o = new ExpressOrder(items, 10, 5);
  ok(o instanceof ExpressOrder);
  ok(o instanceof DiscountedOrder);
  ok(o instanceof Order);
});

test('the base class is unaffected by its subclasses', () => {
  const plain = new Order(items);
  const cheap = new DiscountedOrder(items, 50);
  approx(cheap.total(), 15);
  eq(plain.total(), 30);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the setters run while constructing', () => {
  const p = new Product('  Mug ', 4.5);
  eq(p.name, 'Mug');
  eq(p.price, 4.5);
});

test('a bad price never becomes an object', () => {
  const p = new Product('Mug', 4.5);
  throws(() => new Product('Mug', -1), 'price cannot be negative');
  throws(() => new Product('Mug', '4'), 'price must be a number');
  throws(() => new Product('', 4.5), 'name cannot be empty');
});

test('rejected writes leave the old value in place', () => {
  const p = new Product('Mug', 4.5);
  throws(() => {
    p.price = -1;
  }, 'price cannot be negative');
  throws(() => {
    p.name = '   ';
  }, 'name cannot be empty');
  eq(p.price, 4.5);
  eq(p.name, 'Mug');
});

test('NaN is a number but not a price', () => {
  const p = new Product('Mug', 4.5);
  throws(() => {
    p.price = NaN;
  }, 'price must be a number');
});

test('displayPrice formats two decimals', () => {
  eq(new Product('Mug', 4.5).displayPrice, '$4.50');
  eq(new Product('Pen', 0).displayPrice, '$0.00');
  eq(new Product('Rug', 1200).displayPrice, '$1200.00');
});

test('applyDiscount writes through the setter and chains', () => {
  const p = new Product('Mug', 4.5);
  approx(p.applyDiscount(25).price, 3.375);
  eq(p.displayPrice, '$3.38');
});

test('a discount that would go negative is refused', () => {
  const p = new Product('Mug', 4.5);
  throws(() => p.applyDiscount(200), 'price cannot be negative');
  eq(p.price, 4.5);
});

test('all the state is private — only accessors are visible', () => {
  const p = new Product('Mug', 4.5);
  eq(Object.keys(p), []);
  eq(JSON.stringify(p), '{}');
  ok('price' in p, 'the accessor still lives on the prototype');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('called through the object, every version works', () => {
  const c = new Clicker();
  eq(c.plainClick(), 1);
  eq(c.boundClick(), 2);
  eq(c.arrowClick(), 3);
  eq(c.clicks, 3);
});

test('detached, the plain method loses its this', () => {
  const c = new Clicker();
  const loose = detach(c, 'plainClick');
  throws(loose, 'undefined', 'strict mode leaves this as undefined');
  eq(c.clicks, 0);
});

test('fix 1: the copy bound in the constructor survives', () => {
  const c = new Clicker();
  const loose = detach(c, 'boundClick');
  eq(loose(), 1);
  eq(loose(), 2);
  eq(c.clicks, 2);
});

test('fix 2: the arrow field survives', () => {
  const c = new Clicker();
  const loose = detach(c, 'arrowClick');
  eq(loose(), 1);
  eq(c.clicks, 1);
});

test('fix 3: the wrapper re-attaches the plain method', () => {
  const c = new Clicker();
  const safe = wrap(c, 'plainClick');
  eq(safe(), 1);
  eq(safe(), 2);
});

test('the fixes work as real callbacks', () => {
  const c = new Clicker();
  [1, 2, 3].forEach(detach(c, 'arrowClick'));
  eq(c.clicks, 3);
});

test('what each fix costs: the plain method is the only shared one', () => {
  const a = new Clicker();
  const b = new Clicker();
  ok(a.plainClick === b.plainClick, 'one copy on the prototype');
  ok(a.arrowClick !== b.arrowClick, 'a new closure per instance');
  ok(a.boundClick !== b.boundClick, 'a new bound function per instance');
});

test('the two fixes are own properties, the method is not', () => {
  const c = new Clicker();
  eq(Object.keys(c).sort(), ['arrowClick', 'boundClick', 'clicks']);
  eq(Object.hasOwn(c, 'plainClick'), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('AppError carries a message and a code', () => {
  const e = new AppError('something broke', 500);
  eq(e.message, 'something broke');
  eq(e.code, 500);
  eq(e.name, 'AppError');
});

test('NotFoundError builds its own message and code', () => {
  const e = new NotFoundError('user');
  eq(e.message, 'user not found');
  eq(e.code, 404);
  eq(e.name, 'NotFoundError');
});

test('ValidationError keeps the field it complained about', () => {
  const e = new ValidationError('email');
  eq(e.message, 'invalid email');
  eq(e.code, 422);
  eq(e.field, 'email');
});

test('every one of them is an Error all the way up the chain', () => {
  const e = new NotFoundError('user');
  ok(e instanceof NotFoundError);
  ok(e instanceof AppError);
  ok(e instanceof Error);
  ok(typeof e.stack === 'string');
});

test('a sibling type is not a match', () => {
  const e = new ValidationError('email');
  eq(e instanceof NotFoundError, false);
});

test('statusFor maps types to numbers', () => {
  eq(statusFor(new NotFoundError('user')), 404);
  eq(statusFor(new ValidationError('email')), 422);
  eq(statusFor(new AppError('teapot', 418)), 418);
});

test('anything unknown is a 500', () => {
  eq(statusFor(new Error('boom')), 500);
  eq(statusFor(new TypeError('bad')), 500);
});

test('catching by type is the point of all this', () => {
  const caught = [];
  for (const thrown of [
    new NotFoundError('user'),
    new ValidationError('email'),
    new Error('boom'),
  ]) {
    try {
      throw thrown;
    } catch (err) {
      if (err instanceof NotFoundError) caught.push('missing');
      else if (err instanceof AppError) caught.push('app');
      else caught.push('unknown');
    }
  }
  eq(caught, ['missing', 'app', 'unknown']);
});

