  eq([...d], ['A♠', 'K♥'], 'a one-shot iterator is the classic bug here');
});

test('nested loops each get their own walker', () => {
  const d = new Deck(['A♠', 'K♥']);
  const pairs = [];
  for (const a of d) for (const b of d) pairs.push(a + b);
  eq(pairs, ['A♠A♠', 'A♠K♥', 'K♥A♠', 'K♥K♥']);
