  const admins = new QueryFilter().where('role', 'admin');
  const young = admins.greaterThan('age', 40);
  ok(young !== admins);
  eq(young.run(rows).map((r) => r.name), ['dot']);
  eq(admins.run(rows).map((r) => r.name), ['ada', 'cy', 'dot'], 'untouched');
});

