  Airport.reset();
  const lax = Airport.for('LAX');
  throws(() => {
    lax.code = 'JFK';
  });
  eq(lax.code, 'LAX');
  eq(Object.isFrozen(lax), true);
  eq(String(lax), 'Airport(LAX)');
