  eq(makeBird('Duck', canSwim, canFly).describe(), 'Duck can swim, fly');
  eq(makeBird('Eagle', canFly).describe(), 'Eagle can fly');
  eq(makeBird('Kiwi').describe(), 'Kiwi can nothing');
});

