  for (const key of Object.keys(source)) {
    if (isUnsafeKey(key)) continue;
    const value = source[key];
    if (isPlainObject(value)) {
      const into = isPlainObject(target[key]) ? target[key] : {};
      target[key] = safeMerge(into, value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

