    spawn(guard, { name: `g${i}` })
  );
  ok(army.every((g) => g.rally === army[0].rally), 'one function, 500 objects');
  eq(army[499].rally(), 'g499');
  eq(army.reduce((n, g) => n + Object.getOwnPropertyNames(g).length, 0), 500);
});

