  const guard = extendBehaviour(creature, {});
  const g = spawn(guard, { name: 'Ada', kind: 'guard' });
  creature.salute = function () {
    return `${this.name} salutes`;
  };
  eq(g.salute(), 'Ada salutes', 'lookup happens at call time');
  delete creature.salute;
});

