  const guard = extendBehaviour(creature, {
    rally() {
      return 'standard';
    },
  });
  const a = spawn(guard, { name: 'Ada' });
  const b = spawn(guard, { name: 'Bob' });
  a.rally = () => 'improvised';
  eq(a.rally(), 'improvised');
  eq(b.rally(), 'standard');
  eq(guard.rally(), 'standard');
});

