  #items = [];

  add(name, price, quantity = 1) {
    throw new Error('TODO');
  }

  remove(name) {
    throw new Error('TODO');
  }

  clear() {
    throw new Error('TODO');
  }

  get items() {
    throw new Error('TODO');
  }

  get count() {
    throw new Error('TODO');
  }

  get total() {
    throw new Error('TODO');
  }
}

